weighted_mean <- function(x, w) sum(x * w) / sum(w)
weighted_var <- function(x, w) {
  m <- weighted_mean(x, w)
  sum(w * (x - m)^2) / sum(w)
}
weighted_quantile <- function(x, w, probs = c(0.25, 0.50, 0.75)) {
  keep <- is.finite(x) & is.finite(w) & w > 0
  x <- x[keep]
  w <- w[keep]
  if (!length(x)) return(rep(NA_real_, length(probs)))
  ord <- order(x)
  x <- x[ord]
  w <- w[ord]
  cw <- cumsum(w) / sum(w)
  stats::approx(x = c(0, cw), y = c(x[1L], x), xout = probs, method = "linear", rule = 2, ties = "ordered")$y
}
weighted_binary_summary <- function(x, w, treatment, level) {
  x <- as.character(x) == as.character(level)
  output <- lapply(c(1L, 0L), function(a) {
    idx <- treatment == a
    p <- weighted_mean(as.numeric(x[idx]), w[idx])
    n_raw <- sum(idx)
    c(pseudo_n = n_raw * p, pct = 100 * p)
  })
  p1 <- unname(output[[1L]]["pct"] / 100)
  p0 <- unname(output[[2L]]["pct"] / 100)
  smd <- (p1 - p0) / sqrt((p1 * (1 - p1) + p0 * (1 - p0)) / 2)
  c(de_n = unname(output[[1L]]["pseudo_n"]), de_pct = unname(output[[1L]]["pct"]),
    co_n = unname(output[[2L]]["pseudo_n"]), co_pct = unname(output[[2L]]["pct"]), smd = unname(smd))
}
weighted_continuous_summary <- function(x, w, treatment) {
  output <- lapply(c(1L, 0L), function(a) {
    idx <- treatment == a
    q <- weighted_quantile(x[idx], w[idx])
    c(q1 = q[1L], median = q[2L], q3 = q[3L], mean = weighted_mean(x[idx], w[idx]), variance = weighted_var(x[idx], w[idx]))
  })
  smd <- (unname(output[[1L]]["mean"]) - unname(output[[2L]]["mean"])) /
    sqrt((unname(output[[1L]]["variance"]) + unname(output[[2L]]["variance"])) / 2)
  c(de_q1 = unname(output[[1L]]["q1"]), de_median = unname(output[[1L]]["median"]), de_q3 = unname(output[[1L]]["q3"]),
    co_q1 = unname(output[[2L]]["q1"]), co_median = unname(output[[2L]]["median"]), co_q3 = unname(output[[2L]]["q3"]), smd = unname(smd))
}
format_count_pct <- function(n, p, digits = 1) sprintf(paste0("%.", digits, "f (%.1f)"), n, p)
format_median_iqr <- function(q1, median, q3, digits = 1) sprintf(paste0("%.", digits, "f (%.", digits, "f to %.", digits, "f)"), median, q1, q3)
format_smd <- function(x) {
  if (!is.finite(x)) return("")
  if (abs(x) < 0.001) return("<0.001")
  sprintf("%.3f", abs(x))
}

summarise_specification <- function(trial, spec) {
  imputation_summaries <- lapply(seq_len(20L), function(m) {
    path <- file.path(weight_root, sprintf("weights_%s_imp%02d.rds", trial, m))
    if (!file.exists(path)) stop("Missing locked weight object: ", path)
    saved <- readRDS(path)
    if (!identical(saved$trial, trial) || saved$imputation != m) stop("Weight-object identity check failed: ", path)
    data <- saved$completed_data
    if (!spec$field %in% names(data)) stop("Missing field in locked completed data: ", spec$field)
    treatment <- as.integer(as.character(data$deescalation))
    if (!identical(sort(unique(treatment)), c(0L, 1L))) stop("Unexpected treatment coding in ", path)
    weights <- saved$ato_brlogit$weight
    if (length(weights) != nrow(data) || any(!is.finite(weights)) || any(weights <= 0)) stop("Invalid stored ATO weights in ", path)
    if (identical(spec$type, "continuous")) {
      weighted_continuous_summary(as.numeric(data[[spec$field]]), weights, treatment)
    } else {
      weighted_binary_summary(data[[spec$field]], weights, treatment, spec$level)
    }
  })
  summary <- colMeans(do.call(rbind, imputation_summaries))
  maximum_absolute_smd <- max(abs(vapply(
    imputation_summaries,
    function(x) unname(x["smd"]),
    numeric(1)
  )))
  if (identical(spec$type, "continuous")) {
    c(de = format_median_iqr(summary["de_q1"], summary["de_median"], summary["de_q3"], spec$digits),
      co = format_median_iqr(summary["co_q1"], summary["co_median"], summary["co_q3"], spec$digits),
      smd = format_smd(maximum_absolute_smd))
  } else {
    c(de = format_count_pct(summary["de_n"], summary["de_pct"], spec$digits),
      co = format_count_pct(summary["co_n"], summary["co_pct"], spec$digits),
      smd = format_smd(maximum_absolute_smd))
  }
}

raw_n <- sapply(trials, function(trial) {
  path <- file.path(weight_root, sprintf("weights_%s_imp01.rds", trial))
  x <- readRDS(path)$completed_data$deescalation
  c(deescalation = sum(as.character(x) == "1"), continuation = sum(as.character(x) == "0"))
})

table_rows <- lapply(row_spec, function(spec) {
  if (identical(spec$type, "section")) {
    return(c(Characteristic = spec$label, MRSA_de = "", MRSA_co = "", MRSA_smd = "", PSA_de = "", PSA_co = "", PSA_smd = ""))
  }
  if (identical(spec$type, "categorical_header")) {
    # Categorical SMD is supplied on the header row as the maximum absolute level-specific SMD.
    return(c(Characteristic = spec$label, MRSA_de = "", MRSA_co = "", MRSA_smd = "", PSA_de = "", PSA_co = "", PSA_smd = ""))
  }
  mrsa <- summarise_specification("anti_mrsa", spec)
  psa <- summarise_specification("anti_psa", spec)
  c(Characteristic = spec$label, MRSA_de = mrsa["de"], MRSA_co = mrsa["co"], MRSA_smd = mrsa["smd"], PSA_de = psa["de"], PSA_co = psa["co"], PSA_smd = psa["smd"])
})

# Categorical header SMDs require the maximum absolute SMD over every listed level.
for (i in seq_along(row_spec)) {
  spec <- row_spec[[i]]
  if (!identical(spec$type, "categorical_header")) next
  level_rows <- which(vapply(row_spec, function(x) identical(x$field, spec$field) && identical(x$type, "categorical_level"), logical(1)))
  header_pos <- i
  for (smd_col in c(4L, 7L)) {
    vals <- vapply(level_rows, function(pos) suppressWarnings(as.numeric(gsub("<0.001", "0.0005", table_rows[[pos]][smd_col], fixed = TRUE))), numeric(1))
    max_val <- max(vals, na.rm = TRUE)
    table_rows[[header_pos]][smd_col] <- if (is.finite(max_val)) format_smd(max_val) else ""
    for (pos in level_rows) table_rows[[pos]][smd_col] <- ""
  }
}

