doc <- flextable::body_add_flextable(doc, value = ft)
note <- paste(
  "Data are weighted median (IQR) for continuous variables and weighted No. (%) for categorical variables.",
  "Weights are the locked overlap weights (ATO) from bias-reduced logistic propensity-score models; no model or outcome was refitted.",
  "Weighted counts are normalised within each treatment strategy to its observed sample size and then averaged across 20 multiply imputed data sets, so they are pseudo-counts rather than observed event counts.",
  "For every row, SMD is the maximum absolute standardised mean difference across the 20 completed data sets; for categorical variables, the SMD on the header row is the largest level-specific value.",
  "ATO indicates average treatment effect in the overlap population; ICU, intensive care unit; IQR, interquartile range; MRSA, methicillin-resistant Staphylococcus aureus; SMD, standardised mean difference."
)
doc <- officer::body_add_fpar(
  doc,
  officer::fpar(
    officer::ftext(paste0("Note. ", note), officer::fp_text(font.family = "Times New Roman", font.size = 8))
  )
)
print(doc, target = out_docx)

